<script setup lang="ts">import {computed,ref} from 'vue';import {useRoute} from 'vue-router';import {Mail,Clock,MessageSquare,GitBranch,Octagon} from 'lucide-vue-next';import AppShell from '@/components/zs/AppShell.vue';import PageHeader from '@/components/zs/PageHeader.vue';import Panel from '@/components/zs/Panel.vue';import StatusBadge from '@/components/zs/StatusBadge.vue';import ZButton from '@/components/zs/ZButton.vue';import {useCrmData} from '@/composables/useCrmData';import {setPageMeta} from '@/lib/page-meta';setPageMeta('Automation Detail','Review and control an outreach workflow.');const d=useCrmData(),route=useRoute(),override=ref('');const item=computed(()=>(d.sequences.data.value??[]).find(x=>x.id===route.params.id));const status=computed(()=>override.value||item.value?.status||'Draft');const nodes=[['Send Email 1',Mail],['Wait 3 days',Clock],['Check for reply',MessageSquare],['Send follow-up',Mail],['Wait 5 days',Clock],['Check reply',GitBranch],['Continue or stop',Octagon]];</script>
<template><AppShell><template v-if="item"><PageHeader :title="item.name" :description="`${item.enrolled} enrolled leads · sequence stops when a lead replies`"><template #actions><StatusBadge :status="status"/><ZButton v-if="status==='Active'" variant="outline" @click="override='Paused'">Pause</ZButton><ZButton v-else @click="override='Active'">{{status==='Paused'?'Resume':'Activate'}}</ZButton><ZButton variant="ghost" @click="override='Completed'">Stop</ZButton></template></PageHeader><div class="grid gap-3 xl:grid-cols-[1fr_320px]"><Panel title="Workflow" description="Visual preview only; no scheduling engine is running" body-class="p-5"><ol class="mx-auto max-w-xl"><li v-for="([label,Icon],i) in nodes" :key="String(label)" class="flex flex-col items-center"><div class="flex w-full items-center gap-3 rounded-md border border-line bg-surface p-3"><span class="grid size-8 place-items-center rounded-md bg-primary-subtle text-primary"><component :is="Icon" class="size-4"/></span><span class="flex-1 text-sm font-medium text-content">{{label}}</span><input v-if="String(label).startsWith('Wait')" class="field h-8 w-20" type="number" :value="i===1?3:5"/></div><span v-if="i<nodes.length-1" class="h-5 w-px bg-line-strong"></span></li></ol></Panel><Panel title="Performance" body-class="space-y-4 p-4"><div v-for="[k,v] in Object.entries({'Leads enrolled':item.enrolled,Completed:item.completed,Replied:item.replied,'Open rate':`${item.openRate}%`,'Reply rate':`${item.replyRate}%`})" :key="k" class="flex items-center justify-between"><span class="text-xs text-content-muted">{{k}}</span><strong class="num text-sm text-content">{{v}}</strong></div></Panel></div></template></AppShell></template>
